SELECT sym, (max(bp_max) - min(bp_min)) / min(bp_min) * 100 AS pct_range FROM quotes_daily GROUP BY sym ORDER BY abs(pct_range) DESC LIMIT 20 SETTINGS max_threads=30,enable_parallel_replicas=0,max_parallel_replicas=1,use_query_cache=0,log_queries=1,log_query_settings=1,log_queries_probability=1,log_queries_min_query_duration_ms=0,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,max_result_rows=1000000,result_overflow_mode='throw',log_comment='reader-scaling-20261011T101134Z-pilot' FORMAT Null
